  ('ibiza-wczasy-last-minute', '{"slug": "ibiza-wczasy-last-minute", "title": "Wczasy all inclusive na Ibizie", "destination": "Ibiza, Hiszpania", "category": "packages", "provider": "Example Travel Partner", "originalPrice": 3299, "currentPrice": 2199, "currency": "PLN", "image": "", "affiliateUrl": "https://example.com/aff/ibiza-last-minute", "description": "7 nocy w hotelu 4* z all inclusive, blisko plaży. Przykładowa oferta — edytuj lub usuń w panelu administratora.\n\nW cenie: przelot, transfer, ubezpieczenie.", "validUntil": "2026-11-15", "featured": true, "createdAt": "2026-10-01T10:00:00.000Z"}'::jsonb, '2026-10-01T10:00:00.000Z'),
