  ('lot-rzym-tanie-bilety', '{"slug": "lot-rzym-tanie-bilety", "title": "Tanie bilety lotnicze do Rzymu", "destination": "Rzym, Włochy", "category": "packages", "provider": "Trip", "originalPrice": 620, "currentPrice": 349, "currency": "PLN", "image": "", "affiliateUrl": "https://trip.tpx.lv/39yaJkS9", "links": [{"type": "flights", "label": "Loty", "url": "https://trip.tpx.lv/39yaJkS9"}, {"type": "hotel", "label": "Polcecany nocleg", "url": "https://trip.tpx.lv/EOGK1zO1"}, {"type": "car", "label": "Auto", "url": "https://kiwitaxi.tpx.lv/1z6BkC5u"}], "description": "Lot w obie strony z Warszawy do Rzymu. Przykładowa oferta — edytuj lub usuń w panelu administratora.", "validUntil": "2026-10-30", "featured": true, "createdAt": "2026-10-02T10:00:00.000Z"}'::jsonb, '2026-10-02T10:00:00.000Z')
